"""Verdicts HV1 à HV5 ; corrections OpenMax et LOF (RC3, RC4, nouvelle version de RC1) ; résultat RV1 (précédent v1 et actuel v3). Idempotent."""
import sys, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1] / "src"))
import tp2_journal as J
def last(i): return [e for e in J.entries() if e["id"] == i][-1]
F = "artifacts/results/v3/V_all_units.csv ; V_resume.csv ; V_HV2.csv ; V_HV3.csv"
NOTE_U = " Une unité (p = 0, rotation 1, répétition 0, pli 0) avait été vue au test de fumée avant le calcul complet ; le verdict repose sur les 300 unités (50 blocs rotation × répétition × pli par fichier)."
def verdict(i, statut, preuve, note=""):
    if last(i)["statut"] == "préinscrite": J.add(i, "hypothese", last(i)["titre"], last(i)["texte"], justification="Verdict établi avec la règle de décision préinscrite (voir la version précédente).", statut=statut, preuve=preuve + "  Fichiers : " + F, note=note + NOTE_U)
verdict("HV1", "confirmée", "Perte de macro-F1 des classes connues de p = 0 à p = 0,5 : mots 0,027 ; caractères 0,003 ; Skip-gram −0,031 (il gagne). Caractères moins mots = −0,024 ; Wilcoxon apparié sur 50 blocs, p = 1,3e-4.", "Les caractères sont presque insensibles au bruit : une lettre abîmée ne détruit qu'une partie des n-grammes d'un mot.")
verdict("HV2", "réfutée", "Tendance du macro-F1 avec p (Spearman par bloc, puis Wilcoxon unilatéral, Holm sur 3) : mots rho médian −0,71, p Holm < 1e-5 (décroît) ; caractères −0,09, p Holm 0,17 (pas de tendance significative) ; Skip-gram +0,26, p Holm 0,99 (il MONTE avec le bruit : 0,437 à p = 0 ; 0,468 à p = 0,5).", "Seuls les mots baissent. Skip-gram progresse avec le bruit ; explication possible, NON testée : les fichiers bruités fournissent des contextes plus variés (mots déplacés, remplacés) à l'apprentissage des vecteurs. À tester (augmentation par bruit, phase 2).")
verdict("HV3", "confirmée", "Skip-gram moins TF-IDF mots à chaque p : −0,086 ; −0,065 ; −0,050 ; −0,042 ; −0,041 ; −0,027 (p de 0 à 0,5). Wilcoxon sur 50 blocs, p Holm < 1e-4 pour les six.", "L'écart se réduit avec le bruit (de −0,086 à −0,027) parce que les mots baissent et que Skip-gram monte.")
verdict("HV4", "non tranchée", "Rangs moyens de Friedman : à p = 0, mots 1,42, caractères 1,76, Skip-gram 2,82 ; à p = 0,5, caractères 1,62, mots 1,76, Skip-gram 2,62 (différence critique 0,47 dans les deux cas). Le meilleur change au niveau des estimations (mots puis caractères), mais mots et caractères sont dans la différence critique aux deux niveaux : ni le renversement ni la stabilité ne sont établis. Seul Skip-gram est nettement dernier.", "À préciser avec plus d'unités ; en pratique mots et caractères sont équivalents sur le macro-F1 des classes connues.")
verdict("HV5", "confirmée", "AUROC du MSP (TF-IDF mots) selon p : rho médian −0,31 sur 50 blocs, 30 blocs sur 50 négatifs, Wilcoxon unilatéral p = 0,038. Valeur moyenne de 0,622 à p = 0 à 0,615 à p = 0,5.", "Effet faible, à la limite du seuil ; le résultat est exploratoire dans son esprit (hypothèse déclarée exploratoire).")
if not J.exists("RV1"):
    J.add("RV1", "resultat", "Bloc V : macro-F1 des classes connues (palier A) selon le bruit (précédent v1 et actuel v3)",
          "**Actuel (v3, développement, 50 blocs par fichier, moyenne) :** TF-IDF mots 0,523 ; 0,510 ; 0,510 ; 0,499 ; 0,496 ; 0,496 (p = 0 à 0,5). TF-IDF caractères 0,513 ; 0,520 ; 0,517 ; 0,509 ; 0,508 ; 0,510. Skip-gram IDF 0,437 ; 0,445 ; 0,460 ; 0,458 ; 0,454 ; 0,468.  AUROC du MSP : mots 0,622 à 0,615 ; caractères 0,611 à 0,618 ; Skip-gram 0,564 à 0,563. AUROC de la confiance sur la famille : mots 0,660 à 0,643 ; caractères 0,664 à 0,656 ; Skip-gram 0,599 à 0,590.  **Précédent (notebook v1, étape 8.3, E4a, validation, plat) :** TF-IDF mots 0,493 ; 0,490 ; 0,492 ; 0,481 ; 0,469 ; 0,474 ; Skip-gram IDF 0,405 ; 0,404 ; 0,414 ; 0,399 ; 0,391 ; 0,401.  Les deux séries sont conservées.",
          justification="Dans les deux séries, TF-IDF mots baisse avec le bruit (de 0,02 à 0,03) et Skip-gram reste derrière (de 0,09 à 0,03). Le gain de Skip-gram avec le bruit, absent de la série v1 (plate), est nouveau et n'est pas expliqué. La confiance sur la FAMILLE bat le MSP pour les trois vectorisations et à tous les niveaux de bruit (écart de 0,02 à 0,05) : réplication, sur d'autres fichiers et d'autres vectorisations, de la comparaison exploratoire RC2 (D12), toujours non préinscrite.", preuve=F)
last_rc1 = last("RC1")
if last_rc1["version"] == 1:
    J.add("RC1", "resultat", last_rc1["titre"], last_rc1["texte"] + "  **Correction (calcul C2, 2026-11-07) :** OpenMax corrigé = 0,514 (la valeur 0,465 de la version C1 venait d'une formule lue à l'envers ; voir RC3). Les 27 autres scores sont inchangés. Valeur de LOF : 0,469, inchangée, mais son explication était fausse (voir RC4).",
          justification=last_rc1["justification"], preuve=last_rc1["preuve"], note="Version 2. La note de la version 1 (« OpenMax simplifié ; LOF : grappes denses, explication non testée ») est remplacée : l'explication des grappes denses est réfutée par construction et par diagnostic (RC4) ; OpenMax avait un défaut d'implémentation corrigé (RC3). La version 1 reste dans l'historique.")
if not J.exists("RC3"):
    J.add("RC3", "resultat", "OpenMax : défaut d'implémentation corrigé (C1 contre C2)",
          "OpenMax de la version C1 appliquait la formule de l'article à l'envers : la probabilité de Weibull (qui mesure « loin du signe moyen de la classe ») était utilisée comme son contraire, si bien que plus un log s'éloignait, moins on lui retirait de score. Preuve : sur 15 unités, la version C1 et la version du code de référence de Bendale et Boult sont presque des images miroirs unité par unité (0,29 contre 0,65 ; 0,26 contre 0,70 ; 0,71 contre 0,27). Résultat sur 125 unités : **C1 : AUROC 0,465 ; C2 (corrigé) : 0,514** (écart-type 0,114 ; FPR@95 0,964). OpenMax corrigé est donc proche du hasard.",
          justification="Vérification demandée par l'étudiant (« il faut en être sûr »). Les verdicts HC1 (maximum 0,666) et HC9 (FPR@95 minimum 0,827) ne changent pas : OpenMax n'est ni le meilleur ni le moins mauvais en FPR@95.", preuve="scripts/v3_diag_C.py ; artifacts/results/v3/C_diagnostic_openmax_lof.csv ; C_resume_C2.csv ; v3_blockC.py (versions C1 et C2)")
if not J.exists("RC4"):
    J.add("RC4", "resultat", "LOF : explication « grappes denses » réfutée, cause réelle identifiée",
          "Diagnostic sur 15 unités (3 par rotation). (1) Le code est correct : la formule du LOF recalculée à la main égale celle de scikit-learn dans 15 unités sur 15. (2) L'explication donnée en RC1 version 1 (les logs d'un même nouveau gabarit forment des grappes denses) est fausse par construction : en mode « nouveauté », chaque log de test est jugé seul contre le jeu d'entraînement, la densité des autres logs de test ne joue aucun rôle. (3) Cause réelle : le LOF est le produit de la densité du voisinage dans le jeu d'entraînement par la sparsité propre du log ; la sparsité propre indique l'inconnu (AUROC 0,607, bon sens) mais la densité du voisinage indique le CONNU (0,590 : les logs connus ont des voisinages plus denses) ; le produit tire dans deux sens opposés : AUROC moyen 0,454. (4) Le signe dépend des classes cachées : AUROC moyen par rotation 0,34 ; 0,68 ; 0,44 ; 0,48 ; 0,34 ; sensibilité faible à k (k = 5 : 0,475 ; k = 20 : 0,454 ; k = 50 : 0,448) et à la banque (complète : 0,483).",
          justification="Vérification demandée par l'étudiant. Limite : le diagnostic porte sur 15 unités, non 125.", preuve="scripts/v3_diag_C.py ; artifacts/results/v3/C_diagnostic_openmax_lof.csv")
print(J.render())
